import { useEffect, useState, type FormEvent } from 'react'
import {
  createExpense,
  fetchExpenses,
  ValidationError,
  type Expense,
} from './api'

const FIELDS = ['label', 'amount', 'currency'] as const

export function App() {
  const [expenses, setExpenses] = useState<Expense[]>([])
  const [loading, setLoading] = useState(true)
  const [loadError, setLoadError] = useState<string | null>(null)
  const [errors, setErrors] = useState<Record<string, string>>({})
  const [formError, setFormError] = useState<string | null>(null)
  const [submitting, setSubmitting] = useState(false)

  useEffect(() => {
    const controller = new AbortController()
    fetchExpenses(controller.signal)
      .then(setExpenses)
      .catch((e: unknown) => {
        if (!controller.signal.aborted)
          setLoadError(e instanceof Error ? e.message : 'Failed to load')
      })
      .finally(() => {
        if (!controller.signal.aborted) setLoading(false)
      })
    return () => controller.abort()
  }, [])

  async function onSubmit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault()
    const form = e.currentTarget
    const data = new FormData(form)
    setSubmitting(true)
    setErrors({})
    setFormError(null)
    try {
      const created = await createExpense({
        label: String(data.get('label') ?? '').trim(),
        amount: Number(data.get('amount')),
        currency: String(data.get('currency') ?? '').trim().toUpperCase(),
      })
      setExpenses((prev) => [...prev, created])
      form.reset()
    } catch (err) {
      if (err instanceof ValidationError) {
        setErrors(err.errors)
        const extra = Object.entries(err.errors).filter(
          ([k]) => !(FIELDS as readonly string[]).includes(k),
        )
        if (extra.length) setFormError(extra.map(([, m]) => m).join(' '))
      } else {
        setFormError(err instanceof Error ? err.message : 'Submit failed')
      }
    } finally {
      setSubmitting(false)
    }
  }

  const field = (name: (typeof FIELDS)[number], label: string, type = 'text') => (
    <div>
      <label htmlFor={name}>{label}</label>
      <input
        id={name}
        name={name}
        type={type}
        step={name === 'amount' ? 'any' : undefined}
        aria-invalid={errors[name] ? true : undefined}
        aria-describedby={errors[name] ? `${name}-error` : undefined}
      />
      {errors[name] && (
        <span id={`${name}-error`} role="alert">
          {errors[name]}
        </span>
      )}
    </div>
  )

  return (
    <main>
      <h1>My expenses</h1>
      {loading && <p>Loading…</p>}
      {loadError && <p role="alert">{loadError}</p>}
      {!loading && !loadError && expenses.length === 0 && <p>No expenses yet.</p>}
      {expenses.length > 0 && (
        <ul>
          {expenses.map((x) => (
            <li key={x.id}>
              {x.label} — {x.amount.toFixed(2)} {x.currency} ({x.status})
            </li>
          ))}
        </ul>
      )}

      <h2>New expense</h2>
      <form onSubmit={onSubmit} noValidate>
        {field('label', 'Label')}
        {field('amount', 'Amount', 'number')}
        {field('currency', 'Currency')}
        {formError && <p role="alert">{formError}</p>}
        <button type="submit" disabled={submitting}>
          {submitting ? 'Submitting…' : 'Submit'}
        </button>
      </form>
    </main>
  )
}
